from collections import Counter
def transform(grid):
    h,w=len(grid),len(grid[0])
    cnt=Counter(v for row in grid for v in row)
    bg=cnt.most_common(1)[0][0]
    c=next(v for v in cnt if v!=bg)
    R=[r for r in range(h) if c in grid[r]]
    cset={r:{j for j in range(w) if grid[r][j]==c} for r in R}
    def comparable(a,b): return a<=b or b<=a
    p=1
    while True:
        ok=True
        for i,a in enumerate(R):
            for b in R[i+1:]:
                if a%p==b%p and not comparable(cset[a],cset[b]): ok=False;break
            if not ok:break
        if ok:break
        p+=1
    g=[row[:] for row in grid]
    # union reference per residue class
    ref={}
    for r in R: ref.setdefault(r%p,set()).update(cset[r])
    for r in R:
        for j in ref[r%p]:
            if g[r][j]==bg: g[r][j]=1
    # extras: c-colored cells outside ref -> paint 1 at (r%p, j) if bg there
    for r in R:
        for j in cset[r]:
            if j not in ref[r%p]:
                d=r%p
                if g[d][j]==bg: g[d][j]=1
    return g

