def fill_bands(grid):
    """Every non-background cell is copied to the same relative position in every band delimited by full single-color (non-background) rows and columns."""
    h, w = len(grid), len(grid[0])
    bg = background(grid)
    rseps = {i for i in range(h) if len(set(grid[i])) == 1 and grid[i][0] != bg}
    cseps = {j for j in range(w) if len({r[j] for r in grid}) == 1 and grid[0][j] != bg}
    rb, cb = index_bands(h, rseps), index_bands(w, cseps)
    out = [row[:] for row in grid]
    for i in range(h):
        if i in rseps: continue
        bi = next(k for k, (a, b) in enumerate(rb) if a <= i < b)
        for j in range(w):
            if j in cseps: continue
            v = grid[i][j]
            if v == bg: continue
            bj = next(k for k, (a, b) in enumerate(cb) if a <= j < b)
            for (a, b) in rb:
                for (c, e) in cb:
                    out[a + (i - rb[bi][0])][c + (j - cb[bj][0])] = v
    return out

def frame_border_fill(grid, fill=2):
    """Background cells on the bounding rectangle of the non-background (frame) color become `fill`; a background cell sandwiched vertically or horizontally between two frame cells also becomes `fill`."""
    h,w=len(grid),len(grid[0])
    vals=[v for row in grid for v in row]
    bg=max(set(vals),key=vals.count)
    cells=[(i,j) for i in range(h) for j in range(w) if grid[i][j]!=bg]
    if not cells: return [row[:] for row in grid]
    r0,r1=min(i for i,_ in cells),max(i for i,_ in cells)
    c0,c1=min(j for _,j in cells),max(j for _,j in cells)
    out=[row[:] for row in grid]
    for i in range(r0,r1+1):
        for j in range(c0,c1+1):
            if out[i][j]==bg and (i in (r0,r1) or j in (c0,c1)
                or (i>r0 and i<r1 and grid[i-1][j]!=bg and grid[i+1][j]!=bg)
                or (j>c0 and j<c1 and grid[i][j-1]!=bg and grid[i][j+1]!=bg)):
                out[i][j]=fill
    return out

def fall_down(grid, steps=1):
    """Every cell falls down `steps` rows within its column; cells pushed past the bottom edge are removed."""
    bg = max({v for row in grid for v in row}, key=lambda v: sum(r.count(v) for r in grid))
    h = len(grid); w = len(grid[0])
    out = [[bg] * w for _ in range(h)]
    for r in range(h):
        for c in range(w):
            if grid[r][c] != bg and r + steps < h:
                out[r + steps][c] = grid[r][c]
    return out


def recolor_minority_run(row, new):
    """In a single row made of two runs, the shorter run is recolored to new."""
    from itertools import groupby
    runs=[(k,len(list(g))) for k,g in groupby(row)]
    if len(runs)!=2: return row[:]
    out=[]
    for k,g in groupby(row):
        n=len(list(g)); out += [new if k==min(runs,key=lambda r:r[1])[0] else k]*n
    return out

def recolor_minority_rows(grid, new):
    """Every row made of two runs has its shorter run recolored to new; other rows unchanged."""
    return [recolor_minority_run(r,new) if len(set(r))>1 else r[:] for r in grid]

